    ["Spellslinger"] = "Чарострілець",
    ["Spend %s on available talents. Continue spending to make additional talents become available."] = "Витрачай %s на доступні таланти. Продовжуй витрачати, щоб відкривати додаткові таланти.",
    ["Spend Anima to activate a location for 1 day"] = "Витрать аніму, щоб активувати локацію на 1 день.",
