    ["Use the new search bar to look for specific options"] = "Скористайся новим рядком пошуку, щоб знайти певні параметри.",
    ["Use this option to customize which campsites your characters use."] = "Скористайся цим параметром, щоб налаштувати, які стоянки використовують твої персонажі.",
    ["Use your |cFF00FFFFmount|r to travel faster!"] = "Використовуй свою |cFF00FFFFїздову тварину|r, щоб подорожувати швидше!",
    ["Use {$129597} on a Mana Wyrm."] = "Застосуй {$129597} на манавирма.",
    ["Use {$59542} on the Draenei Survivors."] = "Застосуй {$59542} на вцілілих дренеїв.",
    ["Use |cFF00FFFF%s|r |T%s:16|t while attacking when you have enough rage."] = "Застосовуй |cFF00FFFF%s|r |T%s:16|t під час атаки, коли маєш достатньо люті.",
    ["Use |cFF00FFFFBear Form|r to shapeshift into a bear"] = "Використовуй |cFF00FFFFВедмежу подобу|r, щоб перевтілитися на ведмедя.",
    ["Use |cFF00FFFFCat Form|r to shapeshift into a cat"] = "Використовуй |cFF00FFFFКотячу подобу|r, щоб перевтілитися на кота.",
    ["Use |cFF00FFFFStealth|r to turn invisible and sneak around your foes"] = "Використовуй |cFF00FFFFСкрадання|r, щоб ставати невидимим і прокрадатися повз ворогів.",
    ["User Interface Updates"] = "Оновлення інтерфейсу",
    ["Using higher quality reagents will help the Crafter make your item at a higher quality.\n\n\n\nClick to change which quality will be used."] = "Використання реагентів вищої якості допоможе Ремісникові створити твій предмет із вищою якістю.\n\n\n\nКлацни, щоб змінити, яка якість використовуватиметься.",
    ["Using higher quality reagents will improve the Skill at which you craft items. |n|nClick to change which quality will be used."] = "Використання реагентів вищої якості підвищить Майстерність, з якою ти створюєш предмети.|n|nКлацни, щоб змінити, яка якість використовуватиметься.",
    ["Valeera Sanguinar reached %s."] = "Валіра Сангвінар досягла %s.",
    ["Vanquish foes from Azeroth's past as memories resurface. Available July 30th!"] = "Здолайте ворогів з минулого Азерота, коли спливають спогади. Доступно 30 липня!",
    ["Vanquish powerful elementals in storms that have erupted across Azeroth."] = "Здолайте могутніх елементалів у бурях, що вирували по всьому Азероту.",
    ["Vault of the Wardens"] = "Сховище Вартових",
    ["Ve'nari's gaze feels %s."] = "Погляд Ве'нарі здається %s.",
    ["Vendors"] = "Торговці",
    ["Venthyr Callings"] = "Поклики Вентирів",
    ["Venture into the Archival Assault delve and battle with the new seasonal nemesis, Ky'veza."] = "Вирушайте до Глибини Архівного Штурму й бийтеся з новим сезонним заклятим ворогом, Кай'везою.",
    ["View All Rewards"] = "Усі нагороди",
    ["View all the appearance sets you can collect for your class here."] = "Переглянь тут усі набори образів, які ти можеш зібрати для свого класу.",
    ["View all your quests by clicking this button."] = "Переглянь усі свої завдання, клацнувши цю кнопку.",
    ["View and apply your completed appearance sets here."] = "Переглядай і застосовуй тут свої зібрані набори образів.",
    ["View information about your House here"] = "Переглядай відомості про свій Будинок тут.",
    ["View your Soulbind powers here when away from the Forge of Bonds"] = "Переглядай тут свої сили душезв'язку, коли ти поза Кузнею Уз.",
    ["View your mount in the |cFF00FFFFCollections|r pane"] = "Переглянь свою їздову тварину в розділі |cFF00FFFFЗбірки|r.",
    ["View your new campsite in the Collections menu."] = "Переглянь свою нову стоянку в меню Колекції.",
    ["View your |cFF00FFFFcombat specializations|r"] = "Переглянь свої |cFF00FFFFбойові спеціалізації|r.",
    ["Vim Brineheart is %s."] = "Вім Розсолосерд %s.",
    ["Visions of N'Zoth Revisited"] = "Видіння Н'Зота: Перегляд",
    ["Visit a Barber Shop to explore all-new looks."] = "Завітайте до перукарні й випробуйте геть нові образи.",
    ["Visit our Recruit A Friend Website"] = "Відвідайте наш сайт «Залучити друга»",
    ["Visit the Heirlooms pane to view your heirloom collection."] = "Відкрий вкладку Реліквій роду, щоб переглянути свою колекцію реліквій.",
    ["Visit the Options Menu to start communicating faster with pings."] = "Завітайте до меню налаштувань, щоб швидше спілкуватися за допомогою позначок.",
    ["Visit the Toy Box to view your toy collection."] = "Відкрий Скриню Іграшок, щоб переглянути свою колекцію іграшок.",
    ["Visit the emissary to collect your reward."] = "Відвідай емісара, щоб забрати свою нагороду.",
    ["Visit your Covenant Sanctum to pick up this quest"] = "Відвідай Святилище свого ковенанту, щоб узяти це завдання.",
    ["Vivianne is currently your %s."] = "Вівіанна наразі ваша %s.",
    ["Void-Scarred"] = "Спотворений Порожнечею",
    ["Voidweaver"] = "Ткач Порожнечі",
    ["War Effort"] = "Воєнні Зусилля",
    ["War Mode activates World PvP, increasing quest rewards and experience and enabling PvP Talents in the outdoor world."] = "Режим Війни вмикає світове PvP, підвищуючи нагороди й досвід за завдання та активуючи PvP-таланти у відкритому світі.",
    ["War Within Dungeon"] = "Підземелля Війни Всередині",
    ["War Within Raid"] = "Рейди Війни Всередині",
    ["Warlock Campaign"] = "Кампанія Чорнокнижника",
    ["Warp Stalker"] = "Просторовий переслідувач",
    ["Warrior Campaign"] = "Кампанія Воїна",
    ["Water Elemental"] = "Водяний елементаль",
    ["Water Strider"] = "Водомірка",
    ["Welcome to Housing!"] = "Ласкаво просимо до Житла!",
    ["Welcome to World of Warcraft!"] = "Ласкаво просимо до World of Warcraft!",
    ["When you have a full party click to Start the Mission."] = "Коли група повна, клацни, щоб почати місію.",
    ["While in a party, use Party Sync to more easily quest together."] = "У групі використовуй Синхронізацію групи, щоб легше виконувати завдання разом.",
    ["Whisper"] = "Шепіт",
    ["White and gray items can now be collected for transmog!"] = "Білі та сірі предмети тепер можна збирати для трансмогрифікації!",
    ["Who"] = "Хто",
    ["Wildstalker"] = "Дикий Переслідувач",
    ["Wind Serpent"] = "Вітряний змій",
    ["Winds of Fortune"] = "Вітри Фортуни",
    ["Winter Veil"] = "Зимова Заметіль",
    ["Winter Veil, Turbulent Timeways, Plunderstorm, and more coming!"] = "Свято Зимової Заслони, Бурхливі часові шляхи, Plunderstorm та інше вже на підході!",
    ["WoW's 20th Anniversary"] = "20-та річниця WoW",
    ["Work alongside Decimus to forge your gear into something greater."] = "Працюйте разом з Децимусом, щоб викувати зі свого спорядження щось величніше.",
    ["Work alongside your neighbors to complete endeavors and earn new decor!"] = "Працюйте разом із сусідами, щоб завершувати починання й здобувати новий декор!",
    ["World Events"] = "Світові події",
    ["World PvP"] = "Світове PvP",
    ["World PvP Scenario"] = "Сценарій світового PvP",
    ["Wrathion considers your Warband |5%s."] = "Гнівіон вважає ваш загін %s.",
    ["You are %s with Marasmius."] = "Ви %s із Марасміусом.",
    ["You are %s with the Stitchmasters."] = "Ви %s із Майстрами Швів.",
    ["You are currently %s in Bizmo's Brawlpub."] = "Наразі ви %s у Бійцівському Шинку Бізмо.",
    ["You are currently %s in the Brawl'gar Arena."] = "Наразі ви %s на Арені Брол'гар.",
    ["You are engaging in Player vs. Player combat. While you are participating in Player vs. Player combat the symbol of your alliance will appear next to your portrait and you can be attacked by enemy players."] = "Ти вступаєш у бій «Гравець проти Гравця». Поки ти береш участь у бою «Гравець проти Гравця», біля твого портрета з'являється символ твоєї сторони, і на тебе можуть нападати ворожі гравці.",
    ["You are now Lorewalking. All other quests are hidden while in this mode."] = "Зараз ти на Мандрівці Історіями. Усі інші завдання сховані, поки активний цей режим.",
    ["You are now a ghost. You can return to life by either finding your corpse or talking to a nearby spirit healer.|n|nYour corpse shows up as an icon in the minimap at the upper right hand portion of the screen."] = "Тепер ти привид. Ти можеш повернутися до життя, знайшовши своє тіло або поговоривши з духовним цілителем поблизу.|n|nТвоє тіло показано як значок на мінікарті у верхній правій частині екрана.",
    ["You are now eligible to join battle. Click \"Enter Battle\" in the dialog or right click the battleground icon on the minimap."] = "Тепер ти можеш приєднатися до битви. Натисни «Увійти в бій» у діалоговому вікні або зроби right click на значку поля бою на мінікарті.",
    ["You are now in a queue to enter a battleground.  You may check your status by moving your mouse cursor over the icon on your minimap."] = "Тепер ти в черзі на вхід до поля бою. Ти можеш перевірити свій стан, навівши курсор миші на значок на мінікарті.",
    ["You are now resting, indicated by your portrait glowing yellow. Time spent resting or logged out gives you a temporary bonus to experience from killing monsters.|n|nYou can quickly return to inns to rest by using your hearthstone."] = "Тепер ти відпочиваєш, на що вказує жовте сяйво твого портрета. Час, проведений у відпочинку або поза грою, дає тимчасовий бонус до досвіду за вбивство монстрів.|n|nТи можеш швидко повернутися до корчми на відпочинок, скориставшись каменем повернення.",
    ["You are now the Dungeon Guide."] = "Тепер ти Провідник підземелля.",
    ["You are queued for an activity.\\n\\nGroup Finder queue information appears in this location."] = "Ти в черзі на активність.\n\nВідомості про чергу Пошуку групи показано тут.",
    ["You are rested. Being rested gives you a temporary bonus to experience from killing monsters."] = "Ти відпочилий. Стан відпочинку дає тимчасовий бонус до досвіду за вбивство монстрів.",
    ["You can Recraft previously crafted equipment to change its Optional Reagents or attempt to raise its quality. |n|nClick to select an item to Recraft."] = "Ти можеш Перетворити раніше створене спорядження, щоб змінити його Додаткові реагенти або спробувати підвищити якість.|n|nКлацни, щоб обрати предмет для Перетворення.",
    ["You can add regular abilities to your Skyriding bar to dismount faster for combat"] = "Ти можеш додати звичайні здібності на панель Небесної їзди, щоб швидше спішитися перед боєм.",
    ["You can advertise your guild with a link in chat.|nClick the invite button."] = "Ти можеш рекламувати свою гільдію посиланням у чаті.|nКлацни кнопку запрошення.",
    ["You can apply this look to all your specializations, or just your current one."] = "Ти можеш застосувати цей вигляд до всіх своїх спеціалізацій або лише до поточної.",
    ["You can assign a pet to a Pet Bed using Customize mode."] = "Ти можеш призначити улюбленця на Лежак у Режимі налаштування.",
    ["You can change your community to Cross-Faction in Settings"] = "Ти можеш зробити свою спільноту міжфракційною в налаштуваннях.",
    ["You can create one or multiple items if you have enough Optional Reagents"] = "Ти можеш створити один чи кілька предметів, якщо маєш достатньо додаткових реагентів.",
    ["You can drink to regain your mana faster. |cffffd200Right Click|r on a beverage to drink it.|n|nYou don't need to drink if your class does not use mana."] = "Ти можеш пити, щоб швидше відновлювати ману. |cffffd200Right Click|r на напої, щоб випити його.|n|nТобі не потрібно пити, якщо твій клас не використовує ману.",
    ["You can enter dungeons or find groups for dungeons by using the |cffffd200Dungeon Finder|r. The Dungeon Finder is accessed from the eye button near the middle of your action bar."] = "Ти можеш заходити в підземелля або шукати групи для них за допомогою |cffffd200Пошуку підземель|r. Пошук підземель доступний через кнопку у вигляді ока посередині панелі дій.",
    ["You can equip items by first clicking the |cffffd200Character Info Button|r near the bottom of the screen, and then the |cffffd200Backpack Button|r at the bottom right of your screen.|n|nThen just drag an equippable item from your backpack onto your character."] = "Ти можеш споряджати предмети: спершу натисни |cffffd200Кнопку інформації про персонажа|r унизу екрана, а потім |cffffd200Кнопку наплічника|r у нижньому правому куті екрана.|n|nТоді просто перетягни придатний для спорядження предмет з наплічника на свого персонажа.",
    ["You can go to your class trainer to learn new skills. |cffffd200Right Click|r on trainers to talk to them.|n|nTrainers are found in many towns or cities and always in your starting area. You may have to search around a little to find your trainer."] = "Ти можеш піти до свого вчителя класу, щоб вивчити нові вміння. |cffffd200Right Click|r на вчителях, щоб поговорити з ними.|n|nВчителі є в багатьох селищах і містах, а також завжди у твоїй стартовій місцевості. Можливо, доведеться трохи пошукати, щоб знайти свого вчителя.",
    ["You can have previously crafted equipment Recrafted to change the Optional Reagents or attempt to raise the quality.\n\n\n\nClick to select an item to Recraft."] = "Ти можеш віддати раніше створене спорядження на Перетворення, щоб змінити Додаткові реагенти або спробувати підвищити якість.\n\n\n\nКлацни, щоб обрати предмет для Перетворення.",
    ["You can heal this Companion immediately by spending Anima"] = "Ти можеш миттєво зцілити цього Соратника, витративши аніму.",
    ["You can ignore collision when placing items by pressing %s"] = "Ти можеш ігнорувати зіткнення під час розміщення предметів, натиснувши %s.",
    ["You can invite another player to your group by |cffffd200Right Clicking|r their portrait and selecting the |cffffd200Invite|r option from the popup menu.|n|nYou can leave a group by Right Clicking on your own portrait and choosing the option to leave the party."] = "Ти можеш запросити іншого гравця до своєї групи, зробивши |cffffd200Right Click|r на його портреті й обравши пункт |cffffd200Запросити|r у спливному меню.|n|nТи можеш залишити групу, зробивши Right Click на власному портреті й обравши пункт «Залишити групу».",
    ["You can invite friends from the opposite faction to do instanced content together"] = "Ти можеш запрошувати друзів із протилежної фракції, щоб разом проходити інстансовий контент.",
    ["You can join or leave voice chat here."] = "Тут ти можеш приєднатися до голосового чату або вийти з нього.",
    ["You can learn a new talent in the talent interface.|n|nOpen the talents page by clicking the pulsing |cffffd200Talents Button|r on your action bar."] = "Ти можеш вивчити новий талант у вікні талантів.|n|nВідкрий сторінку талантів, натиснувши пульсуючу |cffffd200Кнопку талантів|r на панелі дій.",
    ["You can look at your reputation with different groups in the world under the Reputation tab.|n|nClick on the |cffffd200Character Info Button|r to find the Reputation tab."] = "Ти можеш переглянути свою репутацію з різними угрупованнями у світі на вкладці «Репутація».|n|nНатисни |cffffd200Кнопку інформації про персонажа|r, щоб знайти вкладку «Репутація».",
    ["You can minimize the Spellbook here"] = "Тут ти можеш згорнути Книгу заклять.",
    ["You can move spells and abilities to your action bar by clicking the |cffffd200Spellbook & Abilities Button|r at the bottom center of the screen and then dragging the ability icon to your action bar.|n|nYou can also use a spell or ability from the Spellbook directly by clicking on it."] = "Ти можеш перемістити закляття та здібності на панель дій, натиснувши |cffffd200Кнопку книги заклять і здібностей|r унизу посередині екрана, а потім перетягнувши значок здібності на панель дій.|n|nТи також можеш скористатися закляттям чи здібністю просто з книги заклять, натиснувши на нього.",
    ["You can now pick a new class specialization. Click here to view your specialization choices."] = "Тепер ти можеш обрати нову спеціалізацію класу. Клацни тут, щоб переглянути варіанти спеціалізацій.",
    ["You can now use |cffffd200Holy Power|r. Your Crusader Strike generates Holy Power, and your Word of Glory can spend it."] = "Тепер ти можеш використовувати |cffffd200Священну силу|r. Твій Удар хрестоносця генерує Священну силу, а Слово слави її витрачає.",
    ["You can only store\\nsoulbound gear."] = "Можна зберігати лише\nспорядження, прив'язане до душі.",
    ["You can press the |cffffd200Spacebar|r to make your character jump. You can use jumping to get past obstacles or just for fun."] = "Натисни |cffffd200Spacebar|r, щоб твій персонаж стрибнув. Стрибки можна використовувати, щоб долати перешкоди, або просто заради розваги.",
    ["You can quickly navigate to different maps by using the dropdowns menu.\\n\\nYou can also view all your quests by clicking 'World'"] = "Ти можеш швидко переходити між різними картами за допомогою спадного меню.\n\nТакож можна переглянути всі свої завдання, клацнувши «Світ».",
    ["You can reply to that player by hitting the R key and then typing a message, or by typing /w <theirname> and then the message."] = "Ти можеш відповісти цьому гравцеві, натиснувши клавішу R і набравши повідомлення, або набравши /w <theirname> і потім повідомлення.",
    ["You can reroll these Anima Powers for a new set of choices"] = "Ти можеш перекинути ці сили аніми, щоб отримати новий набір варіантів.",
    ["You can send a message by hitting the Enter key, typing a message, and then hitting Enter again. Other players nearby will hear what you say."] = "Ти можеш надіслати повідомлення, натиснувши клавішу Enter, набравши текст і натиснувши Enter ще раз. Інші гравці поблизу почують те, що ти скажеш.",
    ["You can set your language here. Changing this will require your message to be reposted."] = "Тут ти можеш обрати свою мову. Її зміна вимагатиме повторної публікації твого повідомлення.",
    ["You can teleport to your House using this button"] = "Ти можеш телепортуватися до свого Будинку за допомогою цієї кнопки.",
    ["You can turn your character by |cffffd200holding the Right Mouse Button|r and moving the mouse.|n|nYou can look around by holding the Left Mouse Button and moving the mouse."] = "Ти можеш повертати свого персонажа, |cffffd200утримуючи праву кнопку миші|r і рухаючи мишу.|n|nТи можеш роздивлятися навколо, утримуючи ліву кнопку миші й рухаючи мишу.",
    ["You can use the |cFF00FFFFSelf Cast Key in Options|r to quickly cast Living Flame on yourself"] = "Ти можеш скористатися |cFF00FFFFклавішею самозастосування в Налаштуваннях|r, щоб швидко творити Живе полум'я на себе.",
    ["You can view Runecarving powers in the Adventure Guide"] = "Ти можеш переглянути сили рунороблення в Путівнику пригод.",
    ["You can view current quests by clicking on the |cffffd200Quest Log Button|r near the bottom middle of your screen.|n|nYou can view quest locations by clicking on the |cffffd200World Map Button|r at the top right of your screen."] = "Ти можеш переглянути поточні завдання, натиснувши |cffffd200Кнопку журналу завдань|r унизу посередині екрана.|n|nТи можеш переглянути місця завдань, натиснувши |cffffd200Кнопку карти світу|r у верхньому правому куті екрана.",
    ["You cannot fire bows and guns without ammunition. To purchase ammunition, visit a gun or bow merchant in a city. To equip ammunition, |cffffd200Right Click|r it."] = "Ти не можеш стріляти з луків і вогнепальної зброї без боєприпасів. Щоб придбати боєприпаси, відвідай торговця зброєю чи луками в місті. Щоб спорядити боєприпаси, |cffffd200Right Click|r на них.",
    ["You cannot use items shown in |cFFFF0000Red|r.\\n\\n"] = "Ти не можеш використовувати предмети, позначені |cFFFF0000червоним|r.\n\n",
    ["You died.  |cFF00FFFFLeft-Click|r on Release Spirit to continue."] = "Ти загинув. |cFF00FFFFКлацни лівою кнопкою|r на «Звільнити дух», щоб продовжити.",
    ["You gained a Hearthstone! Open your bag to see it."] = "Ти отримав камінь повернення! Відкрий сумку, щоб побачити його.",
    ["You got a |cFF00FFFFmount|r!\\n\\nPress |cFF00FFFF%s|r to open your bag."] = "Ти отримав |cFF00FFFFїздову тварину|r!\n\nНатисни |cFF00FFFF%s|r, щоб відкрити сумку.",
    ["You have a Profession Accessory that can be equipped into a Profession Equipment slot."] = "У тебе є Аксесуар професії, який можна вдягти в комірку Спорядження професії.",
    ["You have a Profession Tool that can be equipped into a Profession Equipment slot."] = "У тебе є Інструмент професії, який можна вдягти в комірку Спорядження професії.",
    ["You have a new applicant. Click here to view the applicant now."] = "У тебе новий претендент. Клацни тут, щоб переглянути його заявку.",
    ["You have a new item! Press |cFF00FFFF%s|r to open your bag."] = "У тебе новий предмет! Натисни |cFF00FFFF%s|r, щоб відкрити сумку.",
    ["You have accepted an elite quest. Such quests are best undertaken in a group, for they will take you into areas inhabited by elite creatures.|n|nElite creatures are significantly tougher than normal monsters; however, they are worth more experience. You can tell an elite creature by the golden dragon border around its portrait."] = "Ти взяв елітне завдання. Такі завдання найкраще виконувати в групі, адже вони заведуть тебе в місцини, заселені елітними істотами.|n|nЕлітні істоти значно міцніші за звичайних монстрів, проте дають більше досвіду. Елітну істоту можна впізнати за золотою рамкою-драконом навколо її портрета.",
    ["You have an Optional Reagent that can be used with this recipe. |n|nOptional Reagents let you customize your crafts, but may also increase Recipe Difficulty."] = "У тебе є Додатковий реагент, який можна застосувати з цим рецептом.|n|nДодаткові реагенти дають змогу налаштовувати свої вироби, але можуть також підвищити Складність рецепта.",
    ["You have attracted the attention of a hostile creature.|n|nA red glow means the creature is attacking you. A yellow glow means you are in danger of being attacked. An orange glow means the creature is attacking you, but may soon change targets."] = "Ти привернув увагу ворожої істоти.|n|nЧервоне сяйво означає, що істота нападає на тебе. Жовте сяйво означає, що тобі загрожує напад. Помаранчеве сяйво означає, що істота нападає на тебе, але незабаром може змінити ціль.",
    ["You have gained access to the totem bar! You will gain an action button on this bar whenever you gain access to a new totem element.|n|nThis bar can hold one totem spell per totem element. At higher level you will gain the ability to drop multiple totems at once."] = "Ти отримав доступ до панелі тотемів! На цій панелі з'являтиметься кнопка дії щоразу, коли ти отримуєш доступ до нового тотемного елемента.|n|nЦя панель може вмістити одне тотемне закляття на кожен тотемний елемент. На вищому рівні ти отримаєш можливість ставити кілька тотемів одночасно.",
    ["You have joined a raid group: a group with an increased limit of 40 members, though usually 10 or 25. Raid groups are necessary to enter the most challenging dungeons or to defeat the most powerful enemies, typically at high level.|n|n|cffff2020While in a raid group, you will not earn credit towards most quests. To leave a raid group, Right Click on your character portrait and select Leave party.|r"] = "Ти приєднався до рейдової групи: групи зі збільшеним обмеженням до 40 учасників, хоча зазвичай їх 10 або 25. Рейдові групи потрібні, щоб заходити в найскладніші підземелля чи долати найпотужніших ворогів, як правило, на високому рівні.|n|n|cffff2020Перебуваючи в рейдовій групі, ти не зараховуватимеш прогрес для більшості завдань. Щоб залишити рейдову групу, зроби Right Click на портреті свого персонажа й обери «Залишити групу».|r",
    ["You have learned a new language. Change your spoken language here."] = "Ти вивчив нову мову. Зміни мову, якою розмовляєш, тут.",
    ["You have learned a new spell or ability! Use the |cffffd200Spellbook & Abilities Button|r near the bottom of your screen to open your Spellbook. |cffffd200Left Click and drag|r a spell or ability to move it to your Action Bar.\\n\\nThe Spellbook is organized with passive spells after active ones."] = "Ти вивчив нове закляття або здібність! Скористайся |cffffd200Кнопкою книги заклять і здібностей|r унизу екрана, щоб відкрити книгу заклять. |cffffd200Left Click і перетягни|r закляття чи здібність, щоб перемістити її на панель дій.\n\nУ книзі заклять пасивні закляття розміщено після активних.",
    ["You have learned your first |cffffd200totem|r! Different kinds of totems provide different kinds of benefits. Ultimately, you will be able to use four different totems at one time."] = "Ти вивчив свій перший |cffffd200тотем|r! Різні види тотемів дають різні переваги. Зрештою ти зможеш використовувати чотири різні тотеми одночасно.",
    ["You have new items in your collection"] = "У твоїй колекції є нові предмети.",
    ["You have not collected this appearance yet! Shift Click to begin tracking it."] = "Ти ще не зібрав цей образ! Shift + клац, щоб почати його відстежувати.",
    ["You have obtained a ranged weapon. To use it, first equip the weapon by opening your |cffffd200Character Info|r and your |cffffd200Backpack|r and dragging the item onto your character.|n|nThen, open up your |cffffd200Spellbook|r and drag the |cffffd200Shoot|r or |cffffd200Throw|r ability onto your action bar.|n|nOnly hunters, warriors and rogues may use ranged weapons. Mages, priests and warlocks may use wands."] = "Ти отримав зброю дальнього бою. Щоб скористатися нею, спершу спорядись: відкрий |cffffd200Інформацію про персонажа|r і |cffffd200Наплічник|r та перетягни предмет на свого персонажа.|n|nТоді відкрий |cffffd200Книгу заклять|r і перетягни здібність |cffffd200Постріл|r або |cffffd200Метання|r на панель дій.|n|nЛише мисливці, воїни та розбійники можуть користуватися зброєю дальнього бою. Маги, жерці й чорнокнижники можуть використовувати чарівні палички.",
    ["You have submitted a GM ticket.  You may edit or abandon your ticket here."] = "Ти надіслав запит до ҐМ. Тут ти можеш змінити чи скасувати свій запит.",
    ["You have unlocked a new Recruit A Friend reward."] = "Ти відкрив нову нагороду за «Запроси друга».",
    ["You have unspent Talent points."] = "У вас є невитрачені очки талантів.",
    ["You just received a new piece of Azerite Armor. Open your bag to equip."] = "Ти щойно отримав нову частину азеритової броні. Відкрий сумку, щоб спорядитися нею.",
    ["You may want to invite other players to team up with you to more easily overcome your enemies.|n|nMany difficult quests can be quickly completed in a group, as quest credit is shared by the group. Moreover, groups earn bonus experience, relative to solo players."] = "Можливо, ти захочеш запросити інших гравців об'єднатися з тобою, щоб легше долати ворогів.|n|nБагато складних завдань можна швидко виконати в групі, адже зарахування завдання спільне для всієї групи. Ба більше, групи отримують бонусний досвід порівняно з гравцями-одинаками.",
    ["You must defeat this Blockade mission in order to run other missions in the area."] = "Ти маєш здолати цю місію Блокади, щоб виконувати інші місії в цій місцевості.",
    ["You must pick a new name within the guidelines of our naming policy."] = "Ти маєш обрати нове ім'я згідно з правилами нашої політики іменування.",
    ["You must provide a commission."] = "Ти мусиш указати комісію.",
    ["You now have a keyring to hold your keys.This |cffffd200Keyring Button|r appears to the left of your bags on your action bar."] = "Тепер у тебе є зв'язка для ключів. Ця |cffffd200Кнопка зв'язки ключів|r з'являється ліворуч від твоїх сумок на панелі дій.",
    ["You now have a |cffffd200Pet Action Bar|r, for more control over your pet. In addition, you have the ability to |cffffd200tame beasts|r to gain new pets"] = "Тепер у тебе є |cffffd200Панель дій улюбленця|r для кращого керування ним. Крім того, у тебе є здібність |cffffd200приручати звірів|r, щоб отримувати нових улюбленців",
    ["You now have a |cffffd200pet action bar|r, for more control over your demon. You will be able to summon different kinds of demons for different jobs."] = "Тепер у тебе є |cffffd200панель дій улюбленця|r для кращого керування своїм демоном. Ти зможеш прикликати різні види демонів для різних завдань.",
    ["You pressed |cFF00FFFFEnter|r and opened the chat frame.\\n\\nType messages here to speak to nearby players.\\n\\nPress |cFF00FFFFEnter|r to send the message or |cFF00FFFFEscape|r to cancel."] = "Ти натиснув |cFF00FFFFEnter|r і відкрив вікно чату.\n\nВводь тут повідомлення, щоб говорити з гравцями поблизу.\n\nНатисни |cFF00FFFFEnter|r, щоб надіслати повідомлення, або |cFF00FFFFEscape|r, щоб скасувати.",
    ["You received a quest to kill |cffffd200Blackrock Battle Worgs|r. They are North of the Abbey (where you are now).|nUse the mini-map in the upper right corner to guide you."] = "Ти отримав завдання вбити |cffffd200бойових воргів Блекрок|r. Вони на північ від абатства (де ти зараз).|nКористуйся мінікартою у верхньому правому куті, щоб орієнтуватися.",
    ["You received a quest to kill |cffffd200Bristleback Invaders|r. \\nUse the mini-map in the upper right corner to guide you."] = "Ти отримав завдання вбити |cffffd200загарбників Щетиноспинних|r.\nКористуйся мінікартою у верхньому правому куті, щоб орієнтуватися.",
    ["You received a quest to kill |cffffd200Crazed Leper Gnomes|r. \\nUse the mini-map in the upper right corner to guide you."] = "Ти отримав завдання вбити |cffffd200очманілих прокажених ґномів|r.\nКористуйся мінікартою у верхньому правому куті, щоб орієнтуватися.",
    ["You received a quest to kill |cffffd200Mindless Zombies|r. \\nUse the mini-map in the upper right corner to guide you."] = "Ти отримав завдання вбити |cffffd200бездумних зомбі|r.\nКористуйся мінікартою у верхньому правому куті, щоб орієнтуватися.",
    ["You received a quest to kill |cffffd200Mottled Boar|r. \\nUse the mini-map in the upper right corner to guide you."] = "Ти отримав завдання вбити |cffffd200плямистих вепрів|r.\nКористуйся мінікартою у верхньому правому куті, щоб орієнтуватися.",
    ["You received a quest to kill |cffffd200Rockjaw Invaders|r. \\nUse the mini-map in the upper right corner to guide you."] = "Ти отримав завдання вбити |cffffd200загарбників Скелезубих|r.\nКористуйся мінікартою у верхньому правому куті, щоб орієнтуватися.",
    ["You received a quest to kill |cffffd200Tiki Targets|r. \\nUse the mini-map in the upper right corner to guide you."] = "Ти отримав завдання вбити |cffffd200мішені тікі|r.\nКористуйся мінікартою у верхньому правому куті, щоб орієнтуватися.",
    ["You received a quest to kill |cffffd200Young Nightsabers|r. \\nUse the mini-map in the upper right corner to guide you."] = "Ти отримав завдання вбити |cffffd200молодих нічних шаблезубів|r.\nКористуйся мінікартою у верхньому правому куті, щоб орієнтуватися.",
    ["You unlocked a new Essence slot. Visit the Heart Forge to activate it."] = "Ти відкрив нову комірку есенції. Відвідай Кузню Серця, щоб активувати її.",
    ["You unlocked a new power. Visit the Heart Forge to activate it."] = "Ти відкрив нову силу. Відвідай Кузню Серця, щоб активувати її.",
    ["You will gain extra Skyriding power as you level."] = "З підвищенням рівня ти отримуватимеш додаткову силу Небесної їзди.",
    ["You will see a Breath bar pop up when your character becomes submerged in water. If you run out of breath, you will begin to drown."] = "Коли твій персонаж занурюється під воду, з'являється смужка дихання. Якщо повітря закінчиться, ти почнеш тонути.",
    ["You'll apply your Character Boost at the end of the class trial"] = "Ти застосуєш своє Прискорення персонажа наприкінці випробування класу.",
    ["You're not eligible to be a guide because you have a penalty on your account history."] = "Ти не можеш стати наставником, бо в історії твого облікового запису є стягнення.",
    ["You're not eligible to be a guide due to parental controls."] = "Ти не можеш стати наставником через батьківський контроль.",
    ["You're not eligible to be a guide."] = "Ти не можеш стати наставником.",
    ["You've earned a new class ability! Click here to see see it."] = "Ти здобув нову здібність класу! Клацни тут, щоб переглянути її.",
    ["You've earned the rank of Archivist, %s class."] = "Ви заслужили ранг Архіваріуса, клас %s.",
    ["You've gained |cFF00FFFFexperience|r!\\n\\nYou'll level up when this bar is filled."] = "Ти здобув |cFF00FFFFдосвід|r!\n\nТи підвищиш рівень, коли ця смуга заповниться.",
    ["You've obtained a reagent bag!|n|nOpen your bag."] = "Ти отримав сумку для реагентів!|n|nВідкрий свою сумку.",
    ["You've received Housing Decor!"] = "Ти отримав Декор для житла!",
    ["You've traveled too far away from the Wild Coast.|n|nIf you continue, you'll be removed from the tutorial.|n|nWould you like to go back to the Wild Coast in Dragon Isles?|n|n|n"] = "Ти зайшов надто далеко від Дикого Узбережжя.|n|nЯкщо продовжиш, тебе буде виведено з туторіалу.|n|nХочеш повернутися на Дике Узбережжя на Драконових Островах?|n|n|n",
    ["You've unlocked a Finishing Reagent slot. Finishing Reagents grant benefits when you craft."] = "Ти відкрив комірку Завершального реагенту. Завершальні реагенти дають переваги під час ремесла.",
    ["Your Warband is %s with the Court of Night."] = "Ваш загін %s із Двором Ночі.",
    ["Your actions in the Maw incur the Eye of the Jailer. Filling the bar will increase your threat level."] = "Твої дії в Пащі привертають Око Тюремника. Заповнення смуги підвищить твій рівень загрози.",
    ["Your bags are full so you won't be able to pick up any more loot. To free up some bag space, visit vendor characters and sell them some of your junk.|n|nThere are usually vendors in every city, town or outpost."] = "Твої сумки заповнені, тож ти не зможеш підібрати більше здобичі. Щоб звільнити місце в сумках, відвідай персонажів-торговців і продай їм трохи свого мотлоху.|n|nТорговці зазвичай є в кожному місті, селищі чи на заставі.",
    ["Your character can learn professions such as Cooking or Blacksmithing, which will allow you to find or create items of value.|n|nTo learn more about professions ask a guard in a major city for directions to the profession trainers."] = "Твій персонаж може опанувати професії, як-от Кулінарія чи Ковальство, що дасть змогу знаходити або створювати цінні предмети.|n|nЩоб дізнатися більше про професії, спитай вартового у великому місті, як пройти до вчителів професій.",
    ["Your character can now choose a class specialization. Specializations confer new abilities at level 10, and provide additional abilities at higher level. Most specializations use different attacks or spells than other specializations in the same class.\\n\\nSome specializations allow you to fulfill different roles, such as tanking or healing. You can change your specialization at any time by visiting a class trainer."] = "Тепер твій персонаж може обрати спеціалізацію класу. Спеціалізації дають нові здібності на 10-му рівні та додаткові здібності на вищих рівнях. Більшість спеціалізацій використовують інші атаки чи заклинання, ніж інші спеціалізації того самого класу.\n\nДеякі спеціалізації дозволяють виконувати різні ролі, як-от танкування чи зцілення. Ти можеш змінити спеціалізацію будь-коли, відвідавши тренера класу.",
    ["Your characters share access to a Warbands bank, Dragonflight reputations, and more!"] = "Ваші персонажі спільно користуються банком Бойових Загонів, репутаціями Польоту Драконів та іншим!",
    ["Your followers can be added to the party here."] = "Тут до групи можна додати твоїх прибічників.",
    ["Your guildmaster must pick a new name within the guidelines of our naming policy."] = "Голова твоєї гільдії має обрати нову назву згідно з правилами нашої політики іменування.",
    ["Your hearthstone will teleport you back to this tavern. Try binding at new taverns you find!"] = "Твій камінь повернення телепортує тебе назад до цієї таверни. Спробуй прив'язатися до нових таверн, які знайдеш!",
    ["Your inventory is full. Find a merchant to sell some of the items in your bag."] = "Твій інвентар повний. Знайди торговця, щоб продати частину предметів із сумки.",
    ["Your loot rolls appear here.|n|nItems you win will go to your bags automatically. "] = "Твої кидки на здобич з'являються тут.|n|nВиграні предмети потраплять у твої сумки автоматично. ",
    ["Your order has been placed. Click to view or cancel your order.\n\nYour crafted item will be sent by mail once the order has been fulfilled."] = "Твоє замовлення розміщено. Клацни, щоб переглянути або скасувати його.\n\nСтворений предмет надішлють тобі поштою, щойно замовлення виконають.",
    ["Your previously applied Transmog and legacy outfits are available in Custom Sets."] = "Твоя раніше застосована Трансмогрифікація та спадкові вбрання доступні у Власних наборах.",
    ["Your profession tool and accessories equip here."] = "Тут споряджаються твій інструмент професії та аксесуари.",
    ["Your quests will be listed here based on the Current Map."] = "Тут перелічуються твої завдання залежно від поточної карти.",
    ["[Unbound]"] = "[Не призначено]",
    ["help"] = "довідка",
    ["|Hchannel:PARTY|h[Dungeon Guide]|h %s:\\32"] = "|Hchannel:PARTY|h[Провідник підземелля]|h %s:\\32",
    ["|TInterface\\\\WorldMap\\\\WorldMapArrow:28:28|t marks your location.|n|n"] = "|TInterface\\\\WorldMap\\\\WorldMapArrow:28:28|t позначає твоє місцеперебування.|n|n",
    ["|cFF00FFFFEssence|r is a resource used for spells such as |cFF00FFFFDisintegrate|r.\\n\\nIt recovers naturally over time."] = "|cFF00FFFFЕсенція|r — це ресурс для заклять на кшталт |cFF00FFFFРозпаду|r.\n\nВона відновлюється сама з часом.",
    ["|cFF00FFFFLeft-Click|r a creature to select it."] = "|cFF00FFFFКлацни лівою кнопкою|r на істоту, щоб обрати її.",
    ["|cFF00FFFFLeft-Click|r here to accept the quest."] = "|cFF00FFFFКлацни лівою кнопкою|r тут, щоб прийняти завдання.",
    ["|cFF00FFFFLeft-Click|r here to close the map."] = "|cFF00FFFFКлацни лівою кнопкою|r тут, щоб закрити карту.",
    ["|cFF00FFFFLeft-Click|r here to close."] = "|cFF00FFFFКлацни лівою кнопкою|r тут, щоб закрити.",
    ["|cFF00FFFFLeft-Click|r here to continue the conversation."] = "|cFF00FFFFКлацни лівою кнопкою|r тут, щоб продовжити розмову.",
    ["|cFF00FFFFLeft-Click|r here to make this your home location."] = "|cFF00FFFFКлацни лівою кнопкою|r тут, щоб зробити це місце своїм домом.",
