    ["|cnHIGHLIGHT_FONT_COLOR:Quests you have already completed with another character are hidden from the map and their NPC quest indicators are faded in the world.|n|nYou can change this setting here.|r"] = "|cnHIGHLIGHT_FONT_COLOR:Завдання, які ти вже виконав іншим персонажем, сховані з карти, а позначки завдань над NPC у світі приглушені.|n|nТи можеш змінити це налаштування тут.|r",
    ["|cnHIGHLIGHT_FONT_COLOR:Some currencies are|r|n|cnNORMAL_FONT_COLOR:Warband Transferable.|r|n|cnHIGHLIGHT_FONT_COLOR:Click a currency to initiate a transfer from another character.|r"] = "|cnHIGHLIGHT_FONT_COLOR:Деякі валюти можна|r|n|cnNORMAL_FONT_COLOR:передавати в межах бойової ватаги.|r|n|cnHIGHLIGHT_FONT_COLOR:Клацни валюту, щоб розпочати передачу від іншого персонажа.|r",
    ["|cnHIGHLIGHT_FONT_COLOR:The |r|cnNORMAL_FONT_COLOR:Interact Key|r|cnHIGHLIGHT_FONT_COLOR: allows you to interact with NPCs and objects using a keypress|n|n|r|cnRED_FONT_COLOR:Assign an Interact Key binding under Control options|r"] = "|cnHIGHLIGHT_FONT_COLOR:|r|cnNORMAL_FONT_COLOR:Клавіша взаємодії|r|cnHIGHLIGHT_FONT_COLOR: дає змогу взаємодіяти з NPC та об'єктами одним натисканням|n|n|r|cnRED_FONT_COLOR:Признач клавішу взаємодії в налаштуваннях керування|r",
    ["|cnHIGHLIGHT_FONT_COLOR:This is a|r |cnNORMAL_FONT_COLOR:Warband|r |cnHIGHLIGHT_FONT_COLOR:faction. Reputation gained with this faction is shared across all of your characters.|r"] = "|cnHIGHLIGHT_FONT_COLOR:Це фракція|r |cnNORMAL_FONT_COLOR:бойової ватаги|r|cnHIGHLIGHT_FONT_COLOR:. Репутація, здобута з цією фракцією, спільна для всіх твоїх персонажів.|r",
    ["|cnNORMAL_FONT_COLOR:/ping [@target] Ping Type|r"] = "|cnNORMAL_FONT_COLOR:/ping [@target] Тип пінгу|r",
    ["|cnNORMAL_FONT_COLOR:Concentration|r|nGuarantees higher quality on your next craft. Regenerates slowly over time."] = "|cnNORMAL_FONT_COLOR:Зосередження|r|nГарантує вищу якість наступного виробу. Відновлюється повільно з часом.",
    ["|cnNORMAL_FONT_COLOR:Interact Key|n|r|cnHIGHLIGHT_FONT_COLOR:Press |r|cnNORMAL_FONT_COLOR:%s|r|cnHIGHLIGHT_FONT_COLOR: to Interact with nearby NPCs and objects|r|n|n|cnNORMAL_FONT_COLOR:%d/2 - Interact with an NPC or object|r"] = "|cnNORMAL_FONT_COLOR:Клавіша взаємодії|n|r|cnHIGHLIGHT_FONT_COLOR:Натисни |r|cnNORMAL_FONT_COLOR:%s|r|cnHIGHLIGHT_FONT_COLOR:, щоб взаємодіяти з NPC та об'єктами поблизу|r|n|n|cnNORMAL_FONT_COLOR:%d/2 - Взаємодій з NPC або об'єктом|r",
    ["|cnNORMAL_FONT_COLOR:Patron Orders|r|nCharacters met on your travels may now send you crafting orders. Fulfill these for profession skill, knowledge, and more!"] = "|cnNORMAL_FONT_COLOR:Замовлення покровителів|r|nПерсонажі, яких ти зустрічаєш у мандрах, тепер можуть надсилати тобі ремісничі замовлення. Виконуй їх заради майстерності, знань і не лише!",
    ["|cnNORMAL_FONT_COLOR:Target|r a nearby enemy"] = "|cnNORMAL_FONT_COLOR:Візьми за ціль|r ворога поблизу.",
    ["|cnNORMAL_FONT_COLOR:Warbound|r |cnHIGHLIGHT_FONT_COLOR:gear can be shared with your other characters.|n|nOnce equipped, this gear becomes|r |cnNORMAL_FONT_COLOR:Soulbound.|r"] = "|cnNORMAL_FONT_COLOR:Прив'язане до ватаги|r |cnHIGHLIGHT_FONT_COLOR:спорядження можна передавати іншим твоїм персонажам.|n|nПісля вдягання це спорядження стає|r |cnNORMAL_FONT_COLOR:прив'язаним до душі.|r",
    ["|cnTUTORIAL_BLUE_FONT_COLOR:Aggro|r comes with its own visual effect and a |cnTUTORIAL_BLUE_FONT_COLOR:sense of progression.|r"] = "|cnTUTORIAL_BLUE_FONT_COLOR:Агро|r має власний візуальний ефект і |cnTUTORIAL_BLUE_FONT_COLOR:відчуття прогресу.|r",
    ["|cnTUTORIAL_BLUE_FONT_COLOR:Ping directly|r onto creatures, characters, Cooldown Manager, and action bars."] = "|cnTUTORIAL_BLUE_FONT_COLOR:Пінгуй напряму|r по істотах, персонажах, Менеджері перезарядження та панелях дій.",
    ["|cnTUTORIAL_BLUE_FONT_COLOR:Press and Hold|r your ping key to select a specific ping."] = "|cnTUTORIAL_BLUE_FONT_COLOR:Натисни й утримуй|r клавішу пінгу, щоб обрати конкретний пінг.",
    ["|cnTUTORIAL_BLUE_FONT_COLOR:Press|r the Ping key to drop quick pings in the world."] = "|cnTUTORIAL_BLUE_FONT_COLOR:Натисни|r клавішу пінгу, щоб швидко ставити пінги у світі.",
    ["|cnTUTORIAL_BLUE_FONT_COLOR:Set up macros|r using Pings."] = "|cnTUTORIAL_BLUE_FONT_COLOR:Налаштовуй макроси|r з використанням пінгів.",
